#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_FIELD_LEN 256
#define MAX_ROLES 8
#define AUTH_NTLM 0x01
#define AUTH_KERBEROS 0x02
#define ROLE_ADMIN 0x80
#define ROLE_USER 0x01
#define ROLE_AUDITOR 0x04

typedef struct {
    uint8_t auth_type;
    uint8_t role_mask;
    uint8_t challenge_response[24];
    uint32_t session_id;
    uint8_t relay_verified;
} auth_context_t;

typedef struct {
    char field_name[MAX_FIELD_LEN];
    uint32_t field_len;
    uint8_t *field_data;
    uint8_t requires_role;
} serialized_field_t;

typedef struct {
    uint32_t num_fields;
    serialized_field_t *fields;
    auth_context_t *auth;
} message_t;

static int verify_ntlm_binding(auth_context_t *ctx, uint8_t *channel_binding) {
    /* Verify that the NTLM response is bound to this specific channel.
     * This prevents relay attacks by ensuring the auth was intended for us.
     * We check the MIC (Message Integrity Code) in the NTLM response. */
    if (ctx->auth_type != AUTH_NTLM)
        return 1;

    /* Compare first 16 bytes of challenge_response with channel binding hash */
    uint8_t computed_mic[16];
    for (int i = 0; i < 16; i++) {
        computed_mic[i] = ctx->challenge_response[i] ^ channel_binding[i];
    }

    /* MIC validation: if all XOR results have high bit clear, binding is valid.
     * This is a simplified check representing EPA (Extended Protection for Auth) */
    for (int i = 0; i < 16; i++) {
        if (computed_mic[i] & 0x80)
            return 0;
    }
    return 1;
}

static int check_relay_protection(auth_context_t *ctx, uint8_t *server_challenge) {
    /* EPA-style relay protection: verify the authentication was not relayed
     * from another service by checking channel binding tokens */
    if (ctx->relay_verified)
        return 1;

    uint8_t channel_binding[16];
    /* Derive channel binding from server challenge - in production this would
     * be the TLS channel binding (tls-server-end-point) */
    memcpy(channel_binding, server_challenge, 16);

    int result = verify_ntlm_binding(ctx, channel_binding);
    ctx->relay_verified = result;
    return result;
}

static int authorize_field_access(auth_context_t *ctx, serialized_field_t *field) {
    /* Role-based access control for deserialization.
     * Admin fields require ROLE_ADMIN in the role_mask. */
    if (field->requires_role == 0)
        return 1;
    return (ctx->role_mask & field->requires_role) != 0;
}

int deserialize_message(uint8_t *buf, size_t buf_len, message_t *msg, uint8_t *server_challenge) {
    if (buf_len < 8)
        return -1;

    /* Guard against NULL auth context to avoid a NULL pointer dereference. */
    if (!msg->auth)
        return -1;

    msg->num_fields = *(uint32_t *)buf;
    if (msg->num_fields > 64)
        return -1;

    /* Verify relay protection before processing any fields */
    int relay_safe = check_relay_protection(msg->auth, server_challenge);

    msg->fields = calloc(msg->num_fields, sizeof(serialized_field_t));
    if (!msg->fields)
        return -1;

    size_t offset = 4;
    for (uint32_t i = 0; i < msg->num_fields; i++) {
        if (offset + 5 > buf_len) {
            for (uint32_t j = 0; j < i; j++)
                free(msg->fields[j].field_data);
            free(msg->fields);
            return -1;
        }

        uint8_t name_len = buf[offset++];
        if (offset + name_len > buf_len || name_len >= MAX_FIELD_LEN) {
            for (uint32_t j = 0; j < i; j++)
                free(msg->fields[j].field_data);
            free(msg->fields);
            return -1;
        }
        memcpy(msg->fields[i].field_name, buf + offset, name_len);
        msg->fields[i].field_name[name_len] = '\0';
        offset += name_len;

        if (offset + 5 > buf_len) {
            for (uint32_t j = 0; j < i; j++)
                free(msg->fields[j].field_data);
            free(msg->fields);
            return -1;
        }

        msg->fields[i].requires_role = buf[offset++];
        msg->fields[i].field_len = *(uint32_t *)(buf + offset);
        offset += 4;

        if (msg->fields[i].field_len > buf_len - offset) {
            for (uint32_t j = 0; j < i; j++)
                free(msg->fields[j].field_data);
            free(msg->fields);
            return -1;
        }

        /* Access control gate: check role AND relay protection */
        if (msg->fields[i].requires_role != 0) {
            if (!authorize_field_access(msg->auth, &msg->fields[i])) {
                offset += msg->fields[i].field_len;
                msg->fields[i].field_data = NULL;
                continue;
            }
            /* For privileged fields, relay protection MUST pass.
             * Reject access if channel binding verification failed,
             * regardless of session state. */
            if (!relay_safe) {
                offset += msg->fields[i].field_len;
                msg->fields[i].field_data = NULL;
                continue;
            }
        }

        msg->fields[i].field_data = malloc(msg->fields[i].field_len);
        if (!msg->fields[i].field_data) {
            for (uint32_t j = 0; j < i; j++)
                free(msg->fields[j].field_data);
            free(msg->fields);
            return -1;
        }
        memcpy(msg->fields[i].field_data, buf + offset, msg->fields[i].field_len);
        offset += msg->fields[i].field_len;
    }

    return 0;
}

int process_admin_command(message_t *msg) {
    /* Execute admin commands from deserialized message */
    for (uint32_t i = 0; i < msg->num_fields; i++) {
        if (msg->fields[i].field_data && msg->fields[i].requires_role == ROLE_ADMIN) {
            /* Process admin command - in real code this would modify system state */
            printf("Executing admin command: %s (len=%u)\n",
                   msg->fields[i].field_name, msg->fields[i].field_len);
            return 1;
        }
    }
    return 0;
}
